import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand

__author__ = "Haili Guo"
__copyright__ = "Copyright (C) 2018, Nokia"
__email__ = "haili.guo@nokia-sbell.com"


class ParsePmFile(GenericEMSSIMCommand):
    """Parsepmfile command class."""

    def __init__(
        self,
        connection,
        prompt=None,
        newline_chars=None,
        path=None,
        mfilter=None,
        cfilter=None,
        short=None,
        measurement_=None,
        object_=None,
        runner=None,
    ):
        """
        Parsepmfile command.

        :param connection: moler connection to device, terminal when command is executed.
        :param path: path
        :param mfilter: mfilter
        :param short: short
        :param measurement_: measurement_
        :param object_: object_
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        self.path = path
        self.mfilter = mfilter
        self.cfilter = cfilter
        self.short = short
        self.measurement_ = measurement_
        self.object_ = object_
        super(ParsePmFile, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "parse_pm_file"
        if self.path:
            cmd = cmd + self.path
        elif self.mfilter:
            cmd = f"{cmd} -mfilter {self.mfilter}"
        elif self.cfilter:
            cmd = f"{cmd} -cfilter {self.cfilter}"
        elif self.short:
            cmd = cmd + self.short
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_measurement_param_line(line)
                self._parse_object_param_line(line)
                self._parse_legend_param_line(line)
                self._parse_table_param_line(line)
            except ParsingDone:
                pass  # line has been fully parsed by one of above parse-methods
        return super(ParsePmFile, self).on_new_line(line, is_full_line)

    _re_measurement_param = re.compile(r"Begin of measurement:\s*(?P<Measurement>\S+)")

    def _parse_measurement_param_line(self, line):
        if self._regex_helper.search_compiled(ParsePmFile._re_measurement_param, line):
            self.measurement_ = self._regex_helper.group("Measurement")
            raise ParsingDone

    _re_object_param = re.compile(r"Object:\s*(?P<Object>\S+)")

    def _parse_object_param_line(self, line):
        if self._regex_helper.search_compiled(ParsePmFile._re_object_param, line):
            self.object_ = self._regex_helper.group("Object")
            raise ParsingDone

    _re_legend_param = re.compile(r"(?P<Number>T\d+)\s*=>\s*(?P<Timestamp>\S+)")

    def _parse_legend_param_line(self, line):
        if self.measurement_ and self.object_ and self._regex_helper.search_compiled(ParsePmFile._re_legend_param, line):
            number = self._regex_helper.group("Number")
            if "-STATS" not in self.current_ret:
                self.current_ret["-STATS"] = {}
            if self.measurement_ not in self.current_ret["-STATS"]:
                self.current_ret["-STATS"][self.measurement_] = {}
            if self.object_ not in self.current_ret["-STATS"][self.measurement_]:
                self.current_ret["-STATS"][self.measurement_][self.object_] = {}
            if "-LEGEND" not in self.current_ret["-STATS"][self.measurement_][self.object_]:
                self.current_ret["-STATS"][self.measurement_][self.object_]["-LEGEND"] = {}
            if number not in self.current_ret["-STATS"][self.measurement_][self.object_]["-LEGEND"]:
                self.current_ret["-STATS"][self.measurement_][self.object_]["-LEGEND"][number] = {}
                self.current_ret["-STATS"][self.measurement_][self.object_]["-LEGEND"][number]["-RAW"] = self._regex_helper.group("Timestamp")
                raise ParsingDone

    def _parse_table_param_line(self, line):
        if self._regex_helper.search_compiled(ParsePmFile._re_fourT_line, line):
            return self._parse_table_four_line(line, ParsePmFile._re_fourT_line)
        elif self._regex_helper.search_compiled(ParsePmFile._re_threeT_line, line):
            return self._parse_table_three_line(line, ParsePmFile._re_threeT_line)
        elif self._regex_helper.search_compiled(ParsePmFile._re_twoT_line, line):
            return self._parse_table_two_line(line, ParsePmFile._re_twoT_line)
        elif self._regex_helper.search_compiled(ParsePmFile._re_oneT_line, line):
            return self._parse_table_one_line(line, ParsePmFile._re_oneT_line)

    _re_fourT_line = re.compile(
        r"(?P<COUNTER>\S+)\s*\|\s*(?P<NAME>\S[\w\s_-]+\S)\s*\|\s*(?P<T1>\d+)\s*\|\s*(?P<T2>\d+)\s*\|\s*(?P<T3>\d+)\s*\|\s*(?P<T4>\d+)\s*\|"
    )

    def _parse_table_four_line(self, line, regexp):
        if self.measurement_ and self.object_ and self._regex_helper.search_compiled(regexp, line):
            counter = self._regex_helper.group("COUNTER")
            t1 = self._regex_helper.group("T1")
            t2 = self._regex_helper.group("T2")
            t3 = self._regex_helper.group("T3")
            t4 = self._regex_helper.group("T4")
            if "-COUNTER" not in self.current_ret["-STATS"][self.measurement_][self.object_]:
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"] = {}
            if counter not in self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"]:
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"][counter] = {}
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"][counter]["-NAME"] = self._regex_helper.group("NAME")
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"][counter]["-VAL"] = [t1, t2, t3, t4]
                raise ParsingDone

    _re_threeT_line = re.compile(r"(?P<COUNTER>\S+)\s*\|\s*(?P<NAME>\S[\w\s_-]+\S)\s*\|\s*(?P<T1>\d+)\s*\|\s*(?P<T2>\d+)\s*\|\s*(?P<T3>\d+)\s*\|")

    def _parse_table_three_line(self, line, regexp):
        if self.measurement_ and self.object_ and self._regex_helper.search_compiled(regexp, line):
            counter = self._regex_helper.group("COUNTER")
            t1 = self._regex_helper.group("T1")
            t2 = self._regex_helper.group("T2")
            t3 = self._regex_helper.group("T3")
            if "-COUNTER" not in self.current_ret["-STATS"][self.measurement_][self.object_]:
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"] = {}
            if counter not in self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"]:
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"][counter] = {}
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"][counter]["-NAME"] = self._regex_helper.group("NAME")
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"][counter]["-VAL"] = [t1, t2, t3]
                raise ParsingDone

    _re_twoT_line = re.compile(r"(?P<COUNTER>\S+)\s*\|\s*(?P<NAME>\S[\w\s_-]+\S)\s*\|\s*(?P<T1>\d+)\s*\|\s*(?P<T2>\d+)\s*\|")

    def _parse_table_two_line(self, line, regexp):
        if self.measurement_ and self.object_ and self._regex_helper.search_compiled(regexp, line):
            counter = self._regex_helper.group("COUNTER")
            t1 = self._regex_helper.group("T1")
            t2 = self._regex_helper.group("T2")
            if "-COUNTER" not in self.current_ret["-STATS"][self.measurement_][self.object_]:
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"] = {}
            if counter not in self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"]:
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"][counter] = {}
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"][counter]["-NAME"] = self._regex_helper.group("NAME")
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"][counter]["-VAL"] = [t1, t2]
                raise ParsingDone

    _re_oneT_line = re.compile(r"(?P<COUNTER>\S+)\s*\|\s*(?P<NAME>\S[\w\s_-]+\S)\s*\|\s*(?P<T1>\d+)\s*\|")

    def _parse_table_one_line(self, line, regexp):
        if self.measurement_ and self.object_ and self._regex_helper.search_compiled(regexp, line):
            counter = self._regex_helper.group("COUNTER")
            t1 = self._regex_helper.group("T1")
            if "-COUNTER" not in self.current_ret["-STATS"][self.measurement_][self.object_]:
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"] = {}
            if counter not in self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"]:
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"][counter] = {}
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"][counter]["-NAME"] = self._regex_helper.group("NAME")
                self.current_ret["-STATS"][self.measurement_][self.object_]["-COUNTER"][counter]["-VAL"] = [t1]
                raise ParsingDone


